def _register_namespaces_from_xml_bytes(raw: bytes) -> None:
    """Register namespaces so ElementTree preserves known prefixes."""
    # xmlns:hp="..." or xmlns="..."
    # Use a loose pattern; we only need prefix preservation, not full validation.
    for m in re.finditer(br"\sxmlns:([A-Za-z_][A-Za-z0-9_.-]*)=(['\"])([^'\"]+)\2", raw):
        prefix = m.group(1).decode("ascii", "replace")
        uri = m.group(3).decode("utf-8", "replace")
        if prefix != "xml":
            try:
                ET.register_namespace(prefix, uri)
            except Exception:
                # Best-effort; namespace registration is optional.
                pass

    m_default = re.search(br"\sxmlns=(['\"])([^'\"]+)\1", raw)
    if m_default:
        uri = m_default.group(2).decode("utf-8", "replace")
        try:
            ET.register_namespace("", uri)
        except Exception:
            pass


def _placeholder_keys_in_text(text: str) -> List[str]:
    return [m.group(1).strip() for m in PLACEHOLDER_RE.finditer(text)]


def _replace_placeholders(text: str, data: Dict[str, object], *, context: str) -> str:
    def repl(m: re.Match[str]) -> str:
        key = m.group(1).strip()
        if key not in data:
            raise KeyError(f"Missing placeholder key '{key}' in data (context: {context})")
        val = data[key]
        return "" if val is None else str(val)

    return PLACEHOLDER_RE.sub(repl, text)


def _strip_layout_cache(elem: ET.Element) -> int:
    """Remove line-seg/layout cache elements under elem. Returns count removed."""
    removed = 0
    for child in list(elem):
        name = _local_name(child.tag)
        # HWPX commonly uses <hp:linesegarray> with <hp:lineseg/> children.
        # Remove anything whose localname contains 'lineseg' (case-insensitive).
        if "lineseg" in name.lower():
            elem.remove(child)
            removed += 1
            continue
        removed += _strip_layout_cache(child)
    return removed


@dataclass
class _TSpan:
    el: ET.Element
    start: int
    end: int


def _process_paragraph(p: ET.Element, data: Dict[str, object]) -> bool:
    """Replace placeholders in one <hp:p>. Returns True if modified."""
    t_elems: List[ET.Element] = [e for e in p.iter() if _local_name(e.tag) == "t"]
    if not t_elems:
        return False

    parts: List[str] = [(e.text or "") for e in t_elems]
    full = "".join(parts)
    if "{{" not in full or "}}" not in full:
        return False

    matches = list(PLACEHOLDER_RE.finditer(full))
    if not matches:
        return False

    spans: List[_TSpan] = []
    pos = 0
    for el, txt in zip(t_elems, parts):
        start = pos
        end = pos + len(txt)
        spans.append(_TSpan(el=el, start=start, end=end))
        pos = end

    # Determine whether any placeholder crosses a <hp:t> boundary.
    boundaries = [s.end for s in spans[:-1]]
    spanning = False
    for m in matches:
        s, e = m.span()
        for b in boundaries:
            if s < b < e:
                spanning = True
                break
        if spanning:
            break

    modified = False

    if spanning:
        replaced_full = _replace_placeholders(full, data, context="paragraph")
        if replaced_full != full:
            modified = True
        # Merge into the first <hp:t>
        first = t_elems[0]
        first.text = replaced_full

        # Remove remaining <hp:t> elements (safe even across multiple <hp:run> parents).
        for extra in t_elems[1:]:
            parent = None
            # Find parent by walking from p; ElementTree has no parent pointers.
            # This is O(n) but paragraphs are small.
            for candidate in p.iter():
                for c in list(candidate):
                    if c is extra:
                        parent = candidate
                        break
                if parent is not None:
                    break
            if parent is not None:
                parent.remove(extra)
            else:
                # Fallback: clear text only.
                extra.text = ""

    else:
        # Replace placeholders inside each <hp:t> individually (preserves run segmentation).
        for el in t_elems:
            old = el.text or ""
            if "{{" not in old:
                continue
            new = _replace_placeholders(old, data, context="text-run")
            if new != old:
                el.text = new
                modified = True

    if modified:
        _strip_layout_cache(p)

    return modified


def _process_xml_bytes(raw: bytes, data: Dict[str, object]) -> bytes:
    _register_namespaces_from_xml_bytes(raw)
    encoding, standalone = _extract_xml_decl(raw)

    # ElementTree expects a str/bytes with correct encoding; raw bytes are fine.
    root = ET.fromstring(raw)

    modified_any = False
    for p in [e for e in root.iter() if _local_name(e.tag) == "p"]:
        if _process_paragraph(p, data):
            modified_any = True

    # Serialize back without pretty-printing.
    # Preserve standalone if it existed in the original declaration.
    enc = encoding or "UTF-8"

    body = ET.tostring(root, encoding=enc, xml_declaration=False)

    if encoding is None and standalone is None:
        # No original XML declaration; write body only.
        out = body
    else:
        if standalone is not None:
            decl = f"<?xml version='1.0' encoding='{enc}' standalone='{standalone}'?>\n".encode(
                "ascii", "strict"
            )
        else:
            decl = f"<?xml version='1.0' encoding='{enc}'?>\n".encode("ascii", "strict")
        out = decl + body

    if b"{{" in out or b"}}" in out:
        # If this triggers, it usually means a missing key in JSON or unmatched patterns.
        # Make it fail loudly so the verifier doesn't accept a partially filled report.
        # (But don't throw if the XML didn't have placeholders to begin with.)
        if b"{{" in raw:
            raise RuntimeError("Placeholders remain after processing an XML that contained placeholders")

    return out


def main() -> int:
    with open(INPUT_JSON, "r", encoding="utf-8") as f:
        data: Dict[str, object] = json.load(f)

    with zipfile.ZipFile(INPUT_HWPX, "r") as zin:
        infos = zin.infolist()
        with zipfile.ZipFile(OUTPUT_HWPX, "w") as zout:
            for info in infos:
                raw = zin.read(info.filename)

                out_raw = raw
                if info.filename.lower().endswith(".xml") and b"{{" in raw:
                    out_raw = _process_xml_bytes(raw, data)

                # Preserve compression method per entry when possible.
                compress_type = info.compress_type or zipfile.ZIP_DEFLATED
                zout.writestr(
                    info.filename,
                    out_raw,
                    compress_type=compress_type,
                )

    # Final safety check: ensure no placeholders remain anywhere in the output archive.
    with zipfile.ZipFile(OUTPUT_HWPX, "r") as z:
        for name in z.namelist():
            blob = z.read(name)
            if b"{{" in blob or b"}}" in blob:
                raise RuntimeError(f"Placeholder pattern found in output file: {name}")

    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except Exception as e:
        print(f"ERROR: {e}", file=sys.stderr)
        raise

